inputs.input:
$= 

var mainFonts = {正文字体};
var codeFonts = {代码字体};
var outline_width = {大纲宽度}; 

// 字体
var result = Regex.Replace({html}, @"--(main-fonts|code-fonts):(.*?);", m =>
{
	if(m.Value.Contains("main")) return $"--main-fonts: {mainFonts};";
	else return $"--code-fonts: {codeFonts};";
});

// 大纲宽度
result = Regex.Replace(result, @"(?smx)^\s*\.typora-export-sidebar(\s+\.outline-content)?\s*
\{.+?\}", m =>
{
	return Regex.Replace(m.Value, @"(width):\s*[^;]+;", $"$1: {outline_width};");
});

return result;

